二分查找在有序数组中查找特定元素。

```python
def binary_search(arr, target):
    """二分查找实现"""
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid  # 找到目标，返回索引
        elif arr[mid] < target:
            left = mid + 1  # 目标在右半部分
        else:
            right = mid - 1  # 目标在左半部分

    return -1  # 未找到

# 测试示例
sorted_numbers = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
target = 23
result = binary_search(sorted_numbers, target)
print(f"在数组{sorted_numbers}中查找{target}，结果索引: {result}")

# 递归版本的二分查找
def binary_search_recursive(arr, target, left=0, right=None):
    """递归二分查找"""
    if right is None:
        right = len(arr) - 1

    if left > right:
        return -1

    mid = (left + right) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid+1, right)
    else:
        return binary_search_recursive(arr, target, left, mid-1)

# 查找第一个等于目标值的元素
def binary_search_first(arr, target):
    """查找第一个等于目标值的索引"""
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] >= target:
            if arr[mid] == target:
                result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result
```

**时间复杂度**: O(log n)  
**空间复杂度**: 迭代O(1)，递归O(log n)  
**前提条件**: 数组必须有序

斐波那契数列：每个数字是前两个数字之和。

```python
def fibonacci_recursive(n):
    """递归实现（效率低）"""
    if n <= 1:
        return n
    return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

def fibonacci_iterative(n):
    """迭代实现（推荐）"""
    if n <= 1:
        return n

    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return b

# 测试示例
n = 10
print(f"斐波那契数列前{n}项:")
for i in range(n):
    print(f"F({i}) = {fibonacci_iterative(i)}")

# 使用记忆化优化递归
def fibonacci_memo(n, memo={}):
    """记忆化递归"""
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci_memo(n-1, memo) + fibonacci_memo(n-2, memo)
    return memo[n]

# 动态规划版本
def fibonacci_dp(n):
    """动态规划实现"""
    if n <= 1:
        return n

    dp = [0] * (n+1)
    dp[1] = 1

    for i in range(2, n+1):
        dp[i] = dp[i-1] + dp[i-2]

    return dp[n]

# 生成斐波那契数列
def generate_fibonacci(count):
    """生成指定数量的斐波那契数"""
    if count <= 0:
        return []
    elif count == 1:
        return [0]

    fib_sequence = [0, 1]
    for i in range(2, count):
        fib_sequence.append(fib_sequence[i-1] + fib_sequence[i-2])

    return fib_sequence
```

**时间复杂度**: 递归O(2ⁿ)，迭代O(n)  
**空间复杂度**: 递归O(n)，迭代O(1)

判断一个数是否为素数的各种方法。

```python
def is_prime_basic(n):
    """基础素数判断"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # 检查6k±1的因子
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sieve_of_eratosthenes(limit):
    """埃拉托斯特尼筛法生成素数"""
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            # 标记i的倍数为非素数
            for j in range(i*i, limit+1, i):
                is_prime[j] = False

    # 收集所有素数
    primes = [i for i in range(2, limit+1) if is_prime[i]]
    return primes

# 测试示例
numbers = [2, 3, 4, 17, 25, 29]
for num in numbers:
    print(f"{num} 是素数: {is_prime_basic(num)}")

# 生成指定范围内的素数
primes_up_to_50 = sieve_of_eratosthenes(50)
print(f"50以内的素数: {primes_up_to_50}")

# 米勒-拉宾素数测试（概率性测试，适用于大数）
import random

def is_prime_miller_rabin(n, k=5):
    """米勒-拉宾素数测试"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # 将n-1写成2^r * d的形式
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # 进行k次测试
    for _ in range(k):
        a = random.randint(2, n - 2)
        x = pow(a, d, n)  # 模幂运算

        if x == 1 or x == n - 1:
            continue

        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True
```

**应用场景**: 密码学、数学计算、算法竞赛

判断字符串是否为回文的各种方法。

```python
def is_palindrome_simple(s):
    """简单回文判断"""
    s = ''.join(filter(str.isalnum, s)).lower()  # 去除非字母数字字符并转小写
    return s == s[::-1]

def is_palindrome_two_pointer(s):
    """双指针法回文判断"""
    s = ''.join(filter(str.isalnum, s)).lower()
    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def is_palindrome_recursive(s):
    """递归回文判断"""
    s = ''.join(filter(str.isalnum, s)).lower()

    def helper(s, left, right):
        if left >= right:
            return True
        if s[left] != s[right]:
            return False
        return helper(s, left+1, right-1)

    return helper(s, 0, len(s)-1)

# 测试示例
test_cases = ["A man, a plan, a canal: Panama", "race a car", "hello", "madam"]

for test in test_cases:
    print(f"'{test}' 是回文: {is_palindrome_simple(test)}")

# 查找最长回文子串
def longest_palindrome_substring(s):
    """查找最长回文子串"""
    if not s:
        return ""

    n = len(s)
    start, max_len = 0, 1

    # 中心扩展法
    def expand_around_center(left, right):
        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(n):
        # 奇数长度回文
        len1 = expand_around_center(i, i)
        # 偶数长度回文
        len2 = expand_around_center(i, i+1)

        current_max = max(len1, len2)
        if current_max > max_len:
            max_len = current_max
            start = i - (current_max - 1) // 2

    return s[start:start+max_len]

# 测试最长回文子串
test_strings = ["babad", "cbbd", "a", "ac"]
for s in test_strings:
    result = longest_palindrome_substring(s)
    print(f"'{s}' 的最长回文子串: '{result}'")
```

**应用场景**: 字符串处理、算法面试、文本分析
